// UNSUPPORTED: c++03, c++11, c++14, c++17
// UNSUPPORTED: libcpp-has-no-incomplete-pstl

// <algorithm>, <memory>, <numeric>

// Every ExecutionPolicy overload of the synopses of N5050 ([algorithm.syn], [memory.syn],
// [numeric.ops.overview]; not <linalg>) can be called with the argument kinds its template
// parameters say (forward iterators, not only random access iterators; with and without the
// predicate) and returns the type the synopsis declares. The assertions were generated from the
// declarations of the draft.

#include <algorithm>
#include <concepts>
#include <execution>
#include <functional>
#include <iterator>
#include <memory>
#include <numeric>
#include <utility>

#include "test_iterators.h"

using F0 = forward_iterator<int*>; using F1 = forward_iterator<int*>; using F2 = forward_iterator<int*>; using F3 = forward_iterator<int*>;
using R0 = random_access_iterator<int*>; using R1 = R0; using R2 = R0; using B0 = bidirectional_iterator<int*>; using B1 = B0; using B2 = B0;
using Size = int; using T = int; using Tp = int;
inline auto pred = [](int) { return true; }; inline auto bpred = [](int, int) { return true; }; inline auto bop = [](int a, int) { return a; };
inline auto uop = [](int a) { return a; }; inline auto fn = [](int) {}; inline auto gen = []() { return 0; };
inline int arr[8]{}; inline int arr2[8]{};
template <class I> I mk(int* p) { return I(p); }
inline constexpr auto& seq = std::execution::seq;
static_assert(requires { std::all_of(seq, mk<F0>(arr), mk<F0>(arr), pred); }, "exists: all_of(ForwardIterator first, ForwardIterator last, Predicate pred)");
static_assert(std::same_as<decltype(std::all_of(seq, mk<F0>(arr), mk<F0>(arr), pred)), bool>, "returns: all_of(ForwardIterator first, ForwardIterator last, Predicate pred) -> bool");
static_assert(requires { std::any_of(seq, mk<F0>(arr), mk<F0>(arr), pred); }, "exists: any_of(ForwardIterator first, ForwardIterator last, Predicate pred)");
static_assert(std::same_as<decltype(std::any_of(seq, mk<F0>(arr), mk<F0>(arr), pred)), bool>, "returns: any_of(ForwardIterator first, ForwardIterator last, Predicate pred) -> bool");
static_assert(requires { std::none_of(seq, mk<F0>(arr), mk<F0>(arr), pred); }, "exists: none_of(ForwardIterator first, ForwardIterator last, Predicate pred)");
static_assert(std::same_as<decltype(std::none_of(seq, mk<F0>(arr), mk<F0>(arr), pred)), bool>, "returns: none_of(ForwardIterator first, ForwardIterator last, Predicate pred) -> bool");
static_assert(requires { std::for_each(seq, mk<F0>(arr), mk<F0>(arr), fn); }, "exists: for_each(ForwardIterator first, ForwardIterator last, Function f)");
static_assert(std::same_as<decltype(std::for_each(seq, mk<F0>(arr), mk<F0>(arr), fn)), void>, "returns: for_each(ForwardIterator first, ForwardIterator last, Function f) -> void");
static_assert(requires { std::for_each_n(seq, mk<F0>(arr), 3, fn); }, "exists: for_each_n(ForwardIterator first, Size n, Function f)");
static_assert(std::same_as<decltype(std::for_each_n(seq, mk<F0>(arr), 3, fn)), F0>, "returns: for_each_n(ForwardIterator first, Size n, Function f) -> ForwardIterator");
static_assert(requires { std::find(seq, mk<F0>(arr), mk<F0>(arr), 0); }, "exists: find(ForwardIterator first, ForwardIterator last, const T& value)");
static_assert(std::same_as<decltype(std::find(seq, mk<F0>(arr), mk<F0>(arr), 0)), F0>, "returns: find(ForwardIterator first, ForwardIterator last, const T& value) -> ForwardIterator");
static_assert(requires { std::find_if(seq, mk<F0>(arr), mk<F0>(arr), pred); }, "exists: find_if(ForwardIterator first, ForwardIterator last, Predicate pred)");
static_assert(std::same_as<decltype(std::find_if(seq, mk<F0>(arr), mk<F0>(arr), pred)), F0>, "returns: find_if(ForwardIterator first, ForwardIterator last, Predicate pred) -> ForwardIterator");
static_assert(requires { std::find_if_not(seq, mk<F0>(arr), mk<F0>(arr), pred); }, "exists: find_if_not(ForwardIterator first, ForwardIterator last, Predicate pred)");
