static_assert(requires { std::find_end(seq, mk<F1>(arr), mk<F1>(arr), mk<F2>(arr), mk<F2>(arr)); }, "exists: find_end(ForwardIterator1 first1, ForwardIterator1 last1, ForwardIterator2 first2, ForwardIterator2 last2)");
static_assert(std::same_as<decltype(std::find_end(seq, mk<F1>(arr), mk<F1>(arr), mk<F2>(arr), mk<F2>(arr))), F1>, "returns: find_end(ForwardIterator1 first1, ForwardIterator1 last1, ForwardIterator2 first2, ForwardIterator2 last2) -> ForwardIterator1");
static_assert(requires { std::find_end(seq, mk<F1>(arr), mk<F1>(arr), mk<F2>(arr), mk<F2>(arr), bpred); }, "exists: find_end(ForwardIterator1 first1, ForwardIterator1 last1, ForwardIterator2 first2, ForwardIterator2 last2, BinaryPredicate pred)");
static_assert(std::same_as<decltype(std::find_end(seq, mk<F1>(arr), mk<F1>(arr), mk<F2>(arr), mk<F2>(arr), bpred)), F1>, "returns: find_end(ForwardIterator1 first1, ForwardIterator1 last1, ForwardIterator2 first2, ForwardIterator2 last2, BinaryPredicate pred) -> ForwardIterator1");
static_assert(requires { std::find_first_of(seq, mk<F1>(arr), mk<F1>(arr), mk<F2>(arr), mk<F2>(arr)); }, "exists: find_first_of(ForwardIterator1 first1, ForwardIterator1 last1, ForwardIterator2 first2, ForwardIterator2 last2)");
static_assert(std::same_as<decltype(std::find_first_of(seq, mk<F1>(arr), mk<F1>(arr), mk<F2>(arr), mk<F2>(arr))), F1>, "returns: find_first_of(ForwardIterator1 first1, ForwardIterator1 last1, ForwardIterator2 first2, ForwardIterator2 last2) -> ForwardIterator1");
