static_assert(std::same_as<decltype(std::adjacent_find(seq, mk<F0>(arr), mk<F0>(arr), bpred)), F0>, "returns: adjacent_find(ForwardIterator first, ForwardIterator last, BinaryPredicate pred) -> ForwardIterator");
